package com.behsazan.corebanking.deposit.account.transaction.oracle;

import com.behsazan.corebanking.deposit.account.transaction.domain.DepositTransactionModels.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.Timestamp;
import java.sql.Types;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.*;

@Repository
public class DepositTransactionRepository {
    public record AccountRow(long accountId,String accountNo,String status,String currencyCode) {}
    public record TxLock(long transactionId,long accountId,String type,BigDecimal amount,String currencyCode,LocalDate valueDate,LocalDate bookingDate,String channel,String dc,String status,Long originalTransactionId,String createdBy,long recordVersion) {}
    public record TxRestriction(String mode,BigDecimal maxAmount) {}
    public record AccountLimit(long id,String type,String transactionType,String channel,BigDecimal amountLimit,Long countLimit) {}
    public record RegulatoryRestriction(String type,BigDecimal limitAmount) {}
    public record OriginalPosting(long legId,Long accountId,String accountReference,String dc,BigDecimal amount,String currencyCode,Long subledgerEntryId) {}
    public record IdemRow(String key,Long accountId,String operationType,String payloadHash,String status,String resultReference) {}

    private final NamedParameterJdbcTemplate jdbc;
    private final String schema;
    public DepositTransactionRepository(NamedParameterJdbcTemplate jdbc,@Value("${core-banking.oracle.business-schema:DPS2}") String schema){this.jdbc=jdbc;this.schema=schema;}

    public long next(String sequence){return jdbc.queryForObject("SELECT "+schema+"."+sequence+".NEXTVAL FROM DUAL",Map.of(),Long.class);}

    public Optional<IdemRow> idempotency(String key){String sql="SELECT IDEMPOTENCY_KEY,ACCOUNT_ID,OPERATION_TYPE_CODE,PAYLOAD_HASH,PROCESSING_STATUS_CODE,RESULT_REFERENCE FROM "+schema+".DEPOSIT_OPERATION_IDEMPOTENCY WHERE IDEMPOTENCY_KEY=:key";return jdbc.query(sql,Map.of("key",key),(r,n)->new IdemRow(r.getString(1),r.getObject(2,Long.class),r.getString(3),r.getString(4),r.getString(5),r.getString(6))).stream().findFirst();}
    public void claimIdempotency(long id,String key,long accountId,String op,String hash,String actor,String correlation){jdbc.update("INSERT INTO "+schema+".DEPOSIT_OPERATION_IDEMPOTENCY(OPERATION_IDEMPOTENCY_ID,IDEMPOTENCY_KEY,ACCOUNT_ID,OPERATION_TYPE_CODE,PAYLOAD_HASH,PROCESSING_STATUS_CODE,REQUESTED_BY_USER_ID,REQUESTED_AT,ORIGIN_SYSTEM_CODE,ORIGIN_MODULE_CODE,ORIGIN_REQUEST_REF,CORRELATION_ID,RECORD_VERSION) VALUES(:id,:key,:aid,:op,:hash,'IN_PROGRESS',:actor,SYSTIMESTAMP,'CORE_BANKING','DEPOSIT_TRANSACTION',:key,:corr,1)",new MapSqlParameterSource().addValue("id",id).addValue("key",key).addValue("aid",accountId).addValue("op",op).addValue("hash",hash).addValue("actor",actor).addValue("corr",correlation));}
    public void completeIdempotency(String key,String result){jdbc.update("UPDATE "+schema+".DEPOSIT_OPERATION_IDEMPOTENCY SET PROCESSING_STATUS_CODE='COMPLETED',RESULT_REFERENCE=:result,COMPLETED_AT=SYSTIMESTAMP,RECORD_VERSION=RECORD_VERSION+1 WHERE IDEMPOTENCY_KEY=:key AND PROCESSING_STATUS_CODE='IN_PROGRESS'",new MapSqlParameterSource().addValue("result",result).addValue("key",key));}

    public Optional<AccountRow> account(long id,boolean lock){String sql="SELECT ACCOUNT_ID,ACCOUNT_NO,ACCOUNT_STATUS_CODE,CURRENCY_CODE FROM "+schema+".DEPOSIT_ACCOUNT WHERE ACCOUNT_ID=:id"+(lock?" FOR UPDATE":"");return jdbc.query(sql,Map.of("id",id),(r,n)->new AccountRow(r.getLong(1),r.getString(2),r.getString(3),r.getString(4))).stream().findFirst();}
    public Optional<AccountRow> accountByReference(String ref){String sql="SELECT ACCOUNT_ID,ACCOUNT_NO,ACCOUNT_STATUS_CODE,CURRENCY_CODE FROM "+schema+".DEPOSIT_ACCOUNT WHERE ACCOUNT_NO=:ref";return jdbc.query(sql,Map.of("ref",ref),(r,n)->new AccountRow(r.getLong(1),r.getString(2),r.getString(3),r.getString(4))).stream().findFirst();}

    public void insertTransaction(long id,String ref,String idem,long accountId,String type,BigDecimal amount,String currency,LocalDate valueDate,LocalDate bookingDate,String channel,String dc,Long original,String externalRef,String actor){String sql="INSERT INTO "+schema+".DEPOSIT_TRANSACTION(TRANSACTION_ID,REFERENCE_NO,IDEMPOTENCY_KEY,ACCOUNT_ID,TRANSACTION_TYPE_CODE,AMOUNT,CURRENCY_CODE,VALUE_DATE,BOOKING_DATE,CHANNEL_CODE,DEBIT_CREDIT_CODE,TRANSACTION_STATUS_CODE,ORIGINAL_TRANSACTION_ID,EXTERNAL_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:ref,:idem,:aid,:type,:amount,:currency,:valueDate,:bookingDate,:channel,:dc,'INITIATED',:original,:external,SYSTIMESTAMP,:actor,1)";jdbc.update(sql,new MapSqlParameterSource().addValue("id",id).addValue("ref",ref).addValue("idem",idem).addValue("aid",accountId).addValue("type",type).addValue("amount",amount).addValue("currency",currency).addValue("valueDate",Date.valueOf(valueDate),Types.DATE).addValue("bookingDate",Date.valueOf(bookingDate),Types.DATE).addValue("channel",channel).addValue("dc",dc).addValue("original",original,Types.BIGINT).addValue("external",externalRef,Types.VARCHAR).addValue("actor",actor));}
    public Optional<TxLock> lock(long accountId,long txId){String sql="SELECT TRANSACTION_ID,ACCOUNT_ID,TRANSACTION_TYPE_CODE,AMOUNT,CURRENCY_CODE,VALUE_DATE,BOOKING_DATE,CHANNEL_CODE,DEBIT_CREDIT_CODE,TRANSACTION_STATUS_CODE,ORIGINAL_TRANSACTION_ID,CREATED_BY,RECORD_VERSION FROM "+schema+".DEPOSIT_TRANSACTION WHERE ACCOUNT_ID=:aid AND TRANSACTION_ID=:id FOR UPDATE";return jdbc.query(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("id",txId),(r,n)->new TxLock(r.getLong(1),r.getLong(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getDate(6).toLocalDate(),r.getDate(7).toLocalDate(),r.getString(8),r.getString(9),r.getString(10),r.getObject(11,Long.class),r.getString(12),r.getLong(13))).stream().findFirst();}
    public int transition(long txId,long version,String from,String to,String actor){String sql="UPDATE "+schema+".DEPOSIT_TRANSACTION SET TRANSACTION_STATUS_CODE=:to,UPDATED_AT=SYSTIMESTAMP,UPDATED_BY=:actor,RECORD_VERSION=RECORD_VERSION+1 WHERE TRANSACTION_ID=:id AND TRANSACTION_STATUS_CODE=:from AND RECORD_VERSION=:v";return jdbc.update(sql,new MapSqlParameterSource().addValue("to",to).addValue("actor",actor).addValue("id",txId).addValue("from",from).addValue("v",version));}
    public int forceStatus(long txId,String to,String actor){return jdbc.update("UPDATE "+schema+".DEPOSIT_TRANSACTION SET TRANSACTION_STATUS_CODE=:to,UPDATED_AT=SYSTIMESTAMP,UPDATED_BY=:actor,RECORD_VERSION=RECORD_VERSION+1 WHERE TRANSACTION_ID=:id",new MapSqlParameterSource().addValue("to",to).addValue("actor",actor).addValue("id",txId));}
    public void history(long id,long txId,String from,String to,String reason,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_TRANSACTION_STATUS_HISTORY(TRANSACTION_STATUS_HISTORY_ID,TRANSACTION_ID,FROM_STATUS_CODE,TO_STATUS_CODE,EFFECTIVE_AT,REASON_CODE,ACTOR_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:tx,:from,:to,SYSTIMESTAMP,:reason,:actor,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("tx",txId).addValue("from",from,Types.VARCHAR).addValue("to",to).addValue("reason",reason,Types.VARCHAR).addValue("actor",actor));}
    public void clearValidations(long txId){jdbc.update("DELETE FROM "+schema+".DEPOSIT_TRANSACTION_VALIDATION WHERE TRANSACTION_ID=:id",Map.of("id",txId));}
    public void validation(long id,long txId,String code,String type,String result,String message,String rule,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_TRANSACTION_VALIDATION(TRANSACTION_VALIDATION_ID,TRANSACTION_ID,VALIDATION_CODE,VALIDATION_TYPE_CODE,RESULT_CODE,RESULT_MESSAGE,RULE_REFERENCE,VALIDATED_AT,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:tx,:code,:type,:result,:message,:rule,SYSTIMESTAMP,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("tx",txId).addValue("code",code).addValue("type",type).addValue("result",result).addValue("message",message,Types.VARCHAR).addValue("rule",rule,Types.VARCHAR).addValue("actor",actor));}
    public void authorization(long id,long txId,String requestedBy,String decidedBy,String reason,String actor){authorization(id,txId,"MAKER_CHECKER",requestedBy,decidedBy,reason,actor);}
    public void authorization(long id,long txId,String authorizationType,String requestedBy,String decidedBy,String reason,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_TRANSACTION_AUTHORIZATION(TRANSACTION_AUTHORIZATION_ID,TRANSACTION_ID,AUTHORIZATION_LEVEL,AUTHORIZATION_TYPE_CODE,REQUESTED_BY,DECISION_CODE,DECIDED_BY,DECIDED_AT,REASON_CODE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:tx,1,:authType,:requested,'APPROVED',:decided,SYSTIMESTAMP,:reason,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("tx",txId).addValue("authType",authorizationType).addValue("requested",requestedBy).addValue("decided",decidedBy).addValue("reason",reason,Types.VARCHAR).addValue("actor",actor));}
    public void leg(long id,long txId,int no,Long accountId,String accountRef,String dc,BigDecimal amount,String currency,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_TRANSACTION_LEG(TRANSACTION_LEG_ID,TRANSACTION_ID,LEG_NO,ACCOUNT_ID,ACCOUNT_REFERENCE,DEBIT_CREDIT_CODE,AMOUNT,CURRENCY_CODE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:tx,:no,:aid,:ref,:dc,:amount,:currency,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("tx",txId).addValue("no",no).addValue("aid",accountId,Types.BIGINT).addValue("ref",accountRef).addValue("dc",dc).addValue("amount",amount).addValue("currency",currency).addValue("actor",actor));}
    public void setLegPostingReference(long legId,String ref,String actor){jdbc.update("UPDATE "+schema+".DEPOSIT_TRANSACTION_LEG SET POSTING_REFERENCE=:ref,UPDATED_AT=SYSTIMESTAMP,UPDATED_BY=:actor,RECORD_VERSION=RECORD_VERSION+1 WHERE TRANSACTION_LEG_ID=:id",new MapSqlParameterSource().addValue("ref",ref).addValue("actor",actor).addValue("id",legId));}
    public void transferDetail(long id,long txId,String transferType,String source,String dest,String bank,String purpose,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_TRANSFER_DETAIL(TRANSFER_DETAIL_ID,TRANSACTION_ID,TRANSFER_TYPE_CODE,SOURCE_ACCOUNT_REFERENCE,DESTINATION_ACCOUNT_REFERENCE,DESTINATION_BANK_CODE,PAYMENT_PURPOSE_CODE,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:tx,:type,:src,:dest,:bank,:purpose,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("tx",txId).addValue("type",transferType).addValue("src",source).addValue("dest",dest).addValue("bank",bank,Types.VARCHAR).addValue("purpose",purpose,Types.VARCHAR).addValue("actor",actor));}
    public void cashDetail(long id,long txId,String op,String desk,String teller,String sourceFunds,String cashRef,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_CASH_TRANSACTION_DETAIL(CASH_TRANSACTION_DETAIL_ID,TRANSACTION_ID,CASH_OPERATION_CODE,CASH_DESK_CODE,TELLER_ID,SOURCE_OF_FUNDS_CODE,CASH_MANAGEMENT_TXN_REF,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:tx,:op,:desk,:teller,:funds,:cashRef,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("tx",txId).addValue("op",op).addValue("desk",desk,Types.VARCHAR).addValue("teller",teller,Types.VARCHAR).addValue("funds",sourceFunds,Types.VARCHAR).addValue("cashRef",cashRef).addValue("actor",actor));}
    public void reversal(long id,long original,long reversal,String reason,String actor){jdbc.update("INSERT INTO "+schema+".DEPOSIT_TRANSACTION_REVERSAL(TRANSACTION_REVERSAL_ID,ORIGINAL_TRANSACTION_ID,REVERSAL_TRANSACTION_ID,REVERSAL_REASON_CODE,REVERSAL_STATUS_CODE,REQUESTED_AT,POSTED_AT,CREATED_AT,CREATED_BY,RECORD_VERSION) VALUES(:id,:orig,:rev,:reason,'POSTED',SYSTIMESTAMP,SYSTIMESTAMP,SYSTIMESTAMP,:actor,1)",new MapSqlParameterSource().addValue("id",id).addValue("orig",original).addValue("rev",reversal).addValue("reason",reason).addValue("actor",actor));}

    public int activeDebitHoldCount(long accountId){return jdbc.queryForObject("SELECT COUNT(*) FROM "+schema+".DEPOSIT_ACCOUNT_HOLD WHERE ACCOUNT_ID=:id AND HOLD_STATUS_CODE='ACTIVE' AND HOLD_TYPE_CODE IN ('FULL','DEBIT_ONLY')",Map.of("id",accountId),Integer.class);}
    public int activeCreditHoldCount(long accountId){return jdbc.queryForObject("SELECT COUNT(*) FROM "+schema+".DEPOSIT_ACCOUNT_HOLD WHERE ACCOUNT_ID=:id AND HOLD_STATUS_CODE='ACTIVE' AND HOLD_TYPE_CODE IN ('FULL','CREDIT_ONLY')",Map.of("id",accountId),Integer.class);}
    public List<TxRestriction> txRestrictions(long accountId,String type,String channel,String direction){String sql="SELECT RESTRICTION_MODE_CODE,MAX_AMOUNT FROM "+schema+".DEPOSIT_ACCOUNT_TRANSACTION_RESTRICTION WHERE ACCOUNT_ID=:aid AND STATUS_CODE='ACTIVE' AND VALID_FROM<=SYSTIMESTAMP AND (VALID_TO IS NULL OR VALID_TO>=SYSTIMESTAMP) AND TRANSACTION_TYPE_CODE=:type AND (CHANNEL_CODE IS NULL OR CHANNEL_CODE=:channel) AND (DIRECTION_CODE IS NULL OR DIRECTION_CODE=:direction)";return jdbc.query(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("type",type).addValue("channel",channel).addValue("direction",direction),(r,n)->new TxRestriction(r.getString(1),r.getBigDecimal(2)));}
    public List<AccountLimit> limits(long accountId,String type,String channel){String sql="SELECT ACCOUNT_LIMIT_ID,LIMIT_TYPE_CODE,TRANSACTION_TYPE_CODE,CHANNEL_CODE,AMOUNT_LIMIT,COUNT_LIMIT FROM "+schema+".DEPOSIT_ACCOUNT_LIMIT WHERE ACCOUNT_ID=:aid AND STATUS_CODE='ACTIVE' AND EFFECTIVE_FROM<=SYSTIMESTAMP AND (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=SYSTIMESTAMP) AND (TRANSACTION_TYPE_CODE IS NULL OR TRANSACTION_TYPE_CODE=:type) AND (CHANNEL_CODE IS NULL OR CHANNEL_CODE=:channel)";return jdbc.query(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("type",type).addValue("channel",channel),(r,n)->new AccountLimit(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getObject(6,Long.class)));}
    public List<RegulatoryRestriction> regulatoryRestrictions(long accountId,String type,String channel){String sql="SELECT RESTRICTION_TYPE_CODE,LIMIT_AMOUNT FROM "+schema+".DEPOSIT_ACCOUNT_REGULATORY_RESTRICTION WHERE ACCOUNT_ID=:aid AND STATUS_CODE='ACTIVE' AND VALID_FROM<=SYSTIMESTAMP AND (VALID_TO IS NULL OR VALID_TO>=SYSTIMESTAMP) AND (TRANSACTION_TYPE_CODE IS NULL OR TRANSACTION_TYPE_CODE=:type) AND (CHANNEL_CODE IS NULL OR CHANNEL_CODE=:channel)";return jdbc.query(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("type",type).addValue("channel",channel),(r,n)->new RegulatoryRestriction(r.getString(1),r.getBigDecimal(2)));}
    public BigDecimal postedAmount(long accountId,String type,String channel,LocalDate from,LocalDate to){String sql="SELECT NVL(SUM(AMOUNT),0) FROM "+schema+".DEPOSIT_TRANSACTION WHERE ACCOUNT_ID=:aid AND TRANSACTION_STATUS_CODE='POSTED' AND (:type IS NULL OR TRANSACTION_TYPE_CODE=:type) AND (:channel IS NULL OR CHANNEL_CODE=:channel) AND BOOKING_DATE BETWEEN :from AND :to";return jdbc.queryForObject(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("type",type,Types.VARCHAR).addValue("channel",channel,Types.VARCHAR).addValue("from",Date.valueOf(from),Types.DATE).addValue("to",Date.valueOf(to),Types.DATE),BigDecimal.class);}
    public long postedCount(long accountId,String type,String channel,LocalDate from,LocalDate to){String sql="SELECT COUNT(*) FROM "+schema+".DEPOSIT_TRANSACTION WHERE ACCOUNT_ID=:aid AND TRANSACTION_STATUS_CODE='POSTED' AND (:type IS NULL OR TRANSACTION_TYPE_CODE=:type) AND (:channel IS NULL OR CHANNEL_CODE=:channel) AND BOOKING_DATE BETWEEN :from AND :to";return jdbc.queryForObject(sql,new MapSqlParameterSource().addValue("aid",accountId).addValue("type",type,Types.VARCHAR).addValue("channel",channel,Types.VARCHAR).addValue("from",Date.valueOf(from),Types.DATE).addValue("to",Date.valueOf(to),Types.DATE),Long.class);}

    public List<OriginalPosting> originalPostings(long txId){String sql="SELECT L.TRANSACTION_LEG_ID,L.ACCOUNT_ID,L.ACCOUNT_REFERENCE,L.DEBIT_CREDIT_CODE,L.AMOUNT,L.CURRENCY_CODE,E.SUBLEDGER_ENTRY_ID FROM "+schema+".DEPOSIT_TRANSACTION_LEG L LEFT JOIN "+schema+".DEPOSIT_SUBLEDGER_ENTRY E ON E.TRANSACTION_ID=L.TRANSACTION_ID AND E.TRANSACTION_LEG_ID=L.TRANSACTION_LEG_ID WHERE L.TRANSACTION_ID=:id ORDER BY L.LEG_NO";return jdbc.query(sql,Map.of("id",txId),(r,n)->new OriginalPosting(r.getLong(1),r.getObject(2,Long.class),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getString(6),r.getObject(7,Long.class)));}

    public Optional<TransactionRecord> transaction(long txId){String sql="SELECT TRANSACTION_ID,REFERENCE_NO,IDEMPOTENCY_KEY,ACCOUNT_ID,TRANSACTION_TYPE_CODE,AMOUNT,CURRENCY_CODE,VALUE_DATE,BOOKING_DATE,CHANNEL_CODE,DEBIT_CREDIT_CODE,TRANSACTION_STATUS_CODE,ORIGINAL_TRANSACTION_ID,EXTERNAL_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION FROM "+schema+".DEPOSIT_TRANSACTION WHERE TRANSACTION_ID=:id";return jdbc.query(sql,Map.of("id",txId),(r,n)->new TransactionRecord(r.getLong(1),r.getString(2),r.getString(3),r.getLong(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getDate(8).toLocalDate(),r.getDate(9).toLocalDate(),r.getString(10),r.getString(11),r.getString(12),r.getObject(13,Long.class),r.getString(14),offset(r.getTimestamp(15)),r.getString(16),r.getLong(17))).stream().findFirst();}
    public List<TransactionRecord> list(long accountId){String sql="SELECT TRANSACTION_ID,REFERENCE_NO,IDEMPOTENCY_KEY,ACCOUNT_ID,TRANSACTION_TYPE_CODE,AMOUNT,CURRENCY_CODE,VALUE_DATE,BOOKING_DATE,CHANNEL_CODE,DEBIT_CREDIT_CODE,TRANSACTION_STATUS_CODE,ORIGINAL_TRANSACTION_ID,EXTERNAL_REFERENCE,CREATED_AT,CREATED_BY,RECORD_VERSION FROM "+schema+".DEPOSIT_TRANSACTION WHERE ACCOUNT_ID=:aid ORDER BY TRANSACTION_ID DESC FETCH FIRST 100 ROWS ONLY";return jdbc.query(sql,Map.of("aid",accountId),(r,n)->new TransactionRecord(r.getLong(1),r.getString(2),r.getString(3),r.getLong(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getDate(8).toLocalDate(),r.getDate(9).toLocalDate(),r.getString(10),r.getString(11),r.getString(12),r.getObject(13,Long.class),r.getString(14),offset(r.getTimestamp(15)),r.getString(16),r.getLong(17)));}
    public List<ValidationRecord> validations(long txId){return jdbc.query("SELECT TRANSACTION_VALIDATION_ID,TRANSACTION_ID,VALIDATION_CODE,VALIDATION_TYPE_CODE,RESULT_CODE,RESULT_MESSAGE,RULE_REFERENCE,VALIDATED_AT FROM "+schema+".DEPOSIT_TRANSACTION_VALIDATION WHERE TRANSACTION_ID=:id ORDER BY TRANSACTION_VALIDATION_ID",Map.of("id",txId),(r,n)->new ValidationRecord(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),offset(r.getTimestamp(8))));}
    public List<AuthorizationRecord> authorizations(long txId){return jdbc.query("SELECT TRANSACTION_AUTHORIZATION_ID,TRANSACTION_ID,AUTHORIZATION_LEVEL,AUTHORIZATION_TYPE_CODE,REQUESTED_BY,DECISION_CODE,DECIDED_BY,DECIDED_AT,REASON_CODE FROM "+schema+".DEPOSIT_TRANSACTION_AUTHORIZATION WHERE TRANSACTION_ID=:id ORDER BY AUTHORIZATION_LEVEL",Map.of("id",txId),(r,n)->new AuthorizationRecord(r.getLong(1),r.getLong(2),r.getInt(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),offset(r.getTimestamp(8)),r.getString(9)));}
    public List<TransactionLeg> legs(long txId){return jdbc.query("SELECT TRANSACTION_LEG_ID,TRANSACTION_ID,LEG_NO,ACCOUNT_ID,ACCOUNT_REFERENCE,DEBIT_CREDIT_CODE,AMOUNT,CURRENCY_CODE,POSTING_REFERENCE FROM "+schema+".DEPOSIT_TRANSACTION_LEG WHERE TRANSACTION_ID=:id ORDER BY LEG_NO",Map.of("id",txId),(r,n)->new TransactionLeg(r.getLong(1),r.getLong(2),r.getInt(3),r.getObject(4,Long.class),r.getString(5),r.getString(6),r.getBigDecimal(7),r.getString(8),r.getString(9)));}
    public TransferDetail transfer(long txId){return jdbc.query("SELECT TRANSFER_DETAIL_ID,TRANSACTION_ID,TRANSFER_TYPE_CODE,SOURCE_ACCOUNT_REFERENCE,DESTINATION_ACCOUNT_REFERENCE,DESTINATION_BANK_CODE,PAYMENT_PURPOSE_CODE,ROUTING_REFERENCE FROM "+schema+".DEPOSIT_TRANSFER_DETAIL WHERE TRANSACTION_ID=:id",Map.of("id",txId),(r,n)->new TransferDetail(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8))).stream().findFirst().orElse(null);}
    public CashDetail cash(long txId){return jdbc.query("SELECT CASH_TRANSACTION_DETAIL_ID,TRANSACTION_ID,CASH_OPERATION_CODE,CASH_DESK_CODE,TELLER_ID,CASH_COUNT_REFERENCE,SOURCE_OF_FUNDS_CODE,CASH_MANAGEMENT_TXN_REF,TELLER_SESSION_REF FROM "+schema+".DEPOSIT_CASH_TRANSACTION_DETAIL WHERE TRANSACTION_ID=:id",Map.of("id",txId),(r,n)->new CashDetail(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9))).stream().findFirst().orElse(null);}
    public ReversalRecord reversalByOriginal(long txId){return jdbc.query("SELECT TRANSACTION_REVERSAL_ID,ORIGINAL_TRANSACTION_ID,REVERSAL_TRANSACTION_ID,REVERSAL_REASON_CODE,REVERSAL_STATUS_CODE,APPROVAL_REQUEST_ID,REQUESTED_AT,POSTED_AT FROM "+schema+".DEPOSIT_TRANSACTION_REVERSAL WHERE ORIGINAL_TRANSACTION_ID=:id",Map.of("id",txId),(r,n)->new ReversalRecord(r.getLong(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5),r.getObject(6,Long.class),offset(r.getTimestamp(7)),offset(r.getTimestamp(8)))).stream().findFirst().orElse(null);}

    private static OffsetDateTime offset(Timestamp ts){return ts==null?null:ts.toInstant().atOffset(ZoneOffset.UTC);}
}
